import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.DTisvaUJ.js";const u=JSON.parse('{"title":"语音识别引擎对比","description":"比较Mutelink中的Whisper、Parakeet、Haas、Qwen3-ASR，介绍支持语言、下载容量及选择建议。","frontmatter":{"description":"比较Mutelink中的Whisper、Parakeet、Haas、Qwen3-ASR，介绍支持语言、下载容量及选择建议。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/zh/compare/speech-recognition"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"property":"og:title","content":"语音识别引擎对比 | Mutelink"}],["meta",{"property":"og:description","content":"比较Mutelink中的Whisper、Parakeet、Haas、Qwen3-ASR，介绍支持语言、下载容量及选择建议。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/zh/compare/speech-recognition"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"语音识别引擎对比 | Mutelink"}],["meta",{"name":"twitter:description","content":"比较Mutelink中的Whisper、Parakeet、Haas、Qwen3-ASR，介绍支持语言、下载容量及选择建议。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/compare/speech-recognition"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/compare/speech-recognition"}]]},"headers":[],"relativePath":"zh/compare/speech-recognition.md","filePath":"zh/compare/speech-recognition.md"}'),n={name:"zh/compare/speech-recognition.md"};function i(o,t,h,l,s,c){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="音声認識エンジンの比較" tabindex="-1">语音识别引擎对比 <a class="header-anchor" href="#音声認識エンジンの比較" aria-label="Permalink to &quot;语音识别引擎对比 {#音声認識エンジンの比較}&quot;">​</a></h1><p>可按说话语言选择识别引擎。“对方语音”也可使用相同本地引擎识别他人的声音。</p><h2 id="迷ったら" tabindex="-1">不知道选哪个时 <a class="header-anchor" href="#迷ったら" aria-label="Permalink to &quot;不知道选哪个时 {#迷ったら}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>说话语言</th><th>推荐</th></tr></thead><tbody><tr><td>日语</td><td>Parakeet日语TDT或Haas-ja</td></tr><tr><td>英语</td><td>Parakeet 英语</td></tr><tr><td>其他语言或需要自动识别语言时</td><td>Qwen3-ASR或Whisper turbo</td></tr><tr><td>电脑性能较低时</td><td>Web Speech（云端）</td></tr></tbody></table><h2 id="エンジンの一覧" tabindex="-1">引擎一览 <a class="header-anchor" href="#エンジンの一覧" aria-label="Permalink to &quot;引擎一览 {#エンジンの一覧}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>引擎</th><th>运行位置</th><th>语言</th><th>下载</th><th>耗时占语音时长</th><th>特点</th></tr></thead><tbody><tr><td>Parakeet日语TDT</td><td>本机</td><td>日语</td><td>约1.0GB</td><td>约3.5%</td><td>快速准确，包含标点</td></tr><tr><td>Haas-ja</td><td>本机</td><td>日语</td><td>约480MB</td><td>约13%</td><td>普通对话略准于Parakeet日语TDT，自行输出汉字与标点</td></tr><tr><td>Parakeet英语</td><td>本机</td><td>英语及其他欧洲语言</td><td>约670MB</td><td>约5%</td><td>快，含标点和大小写；不支持日中韩</td></tr><tr><td>Qwen3-ASR</td><td>本机</td><td>日英中韩等52种语言</td><td>约1.0GB</td><td>约10—20%</td><td>单个模型支持多语言，自动识别语言</td></tr><tr><td>Whisper turbo</td><td>本机</td><td>日英中韩等</td><td>约1.0GB</td><td>约30%</td><td>自动识别语言，比其他本地引擎耗时更多</td></tr><tr><td>Web Speech（Microsoft）</td><td>云端</td><td>多语言</td><td>无</td><td>—</td><td>无需模型下载，需要网络，音频发往Microsoft</td></tr><tr><td>Google（非官方、实验性）</td><td>云端</td><td>多语言</td><td>无</td><td>—</td><td>非官方API，可能不经通知停止使用，音频发往Google</td></tr></tbody></table><ul><li>本地引擎仅使用CPU，不使用GPU。声音不会发送到电脑外。</li><li>速度为作者Ryzen 7 7700上的参考值。“约5%”表示10秒语音约需0.5秒识别。</li><li>Haas-ja约13%由既有相对值（约为Parakeet日语TDT的3.6倍），以约3.5%为基准换算并四舍五入。</li><li>仅Qwen3-ASR和Whisper turbo支持将语言设为自动。</li></ul><h2 id="合成音声を聞かせた結果" tabindex="-1">识别合成语音的结果 <a class="header-anchor" href="#合成音声を聞かせた結果" aria-label="Permalink to &quot;识别合成语音的结果 {#合成音声を聞かせた結果}&quot;">​</a></h2><p>将Qwen3-TTS和Irodori-TTS生成的相同音频送入各引擎，与原文比较，可用于观察<strong>各引擎的倾向差异</strong>。</p><p>各项为“平均错误率 · 完全匹配句数/30”。错误率越低越准确。</p><h3 id="日本語-読みで比べたもの" tabindex="-1">日语（按读音比较） <a class="header-anchor" href="#日本語-読みで比べたもの" aria-label="Permalink to &quot;日语（按读音比较） {#日本語-読みで比べたもの}&quot;">​</a></h3><p>Parakeet日语TDT的汉字由应用后处理修正，因此此处将双方转为平假名后比较。</p><table tabindex="0"><thead><tr><th>音频来源</th><th>Whisper turbo</th><th>Qwen3-ASR</th><th>Parakeet日语TDT</th><th>Haas-ja</th></tr></thead><tbody><tr><td>Irodori-TTS</td><td>5.6% · 25/30</td><td>13.8% · 21/30</td><td>6.9% · 20/30</td><td>4.5% · 25/30</td></tr><tr><td>Qwen3-TTS</td><td>14.9% · 23/30</td><td>17.3% · 19/30</td><td>11.1% · 23/30</td><td>9.7% · 23/30</td></tr></tbody></table><h3 id="ほかの言語-qwen3-ttsの音声" tabindex="-1">其他语言（Qwen3-TTS音频） <a class="header-anchor" href="#ほかの言語-qwen3-ttsの音声" aria-label="Permalink to &quot;其他语言（Qwen3-TTS音频） {#ほかの言語-qwen3-ttsの音声}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>语言</th><th>Whisper turbo</th><th>Qwen3-ASR</th><th>Parakeet 英语</th></tr></thead><tbody><tr><td>英语</td><td>2.1% · 27/30</td><td>0.8% · 28/30</td><td>2.9% · 25/30</td></tr><tr><td>中文</td><td>5.4% · 25/30</td><td>0.3% · 29/30</td><td>不支持</td></tr><tr><td>韩语</td><td>2.4% · 27/30</td><td>4.0% · 24/30</td><td>不支持</td></tr><tr><td>德语</td><td>3.9% · 26/30</td><td>4.4% · 25/30</td><td>4.7% · 23/30</td></tr><tr><td>西班牙语</td><td>4.2% · 27/30</td><td>2.8% · 28/30</td><td>3.9% · 25/30</td></tr><tr><td>法语</td><td>6.6% · 24/30</td><td>6.1% · 27/30</td><td>2.5% · 26/30</td></tr><tr><td>意大利语</td><td>6.4% · 24/30</td><td>11.2% · 21/30</td><td>5.9% · 21/30</td></tr><tr><td>葡萄牙语</td><td>6.2% · 26/30</td><td>7.4% · 24/30</td><td>6.5% · 21/30</td></tr><tr><td>俄语</td><td>2.6% · 26/30</td><td>9.3% · 22/30</td><td>4.4% · 25/30</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">结果的限制</p><ul><li>测试使用合成语音而非真人麦克风录音。真实人声、杂音和说话习惯会改变结果。</li><li>每种语言使用30句AI生成的日常短句，未经母语者确认。</li><li>日中韩按字符计错，其他语言按单词计错。数字写法（“3”与“三”）和改写也会计为错误。</li><li>未经过应用的汉字转换、标点修正等后处理。</li><li>未测试Web Speech和Google云端引擎。</li></ul></div>',16)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
